package cn.huankan.event;
import java.util.*;import java.time.Instant;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/macro-research")public class MacroResearchController {private final MacroResearchService s;public MacroResearchController(MacroResearchService service){s=service;}public record Analyze(String series,Instant asOf){}public record Page(int page){}@PostMapping("/catalog")public Object catalog(){return s.catalog();}@PostMapping("/analyze")public Object analyze(@RequestBody Analyze q){return s.analyze(q.series(),q.asOf());}@PostMapping("/history")public Object history(@RequestBody Page q){return s.history(q.page());}@ExceptionHandler({IllegalArgumentException.class,org.springframework.dao.DataAccessException.class})public org.springframework.http.ResponseEntity<?> invalid(){return org.springframework.http.ResponseEntity.badRequest().body(Map.of("message","研究输入证据、同口径条件或截止时间不足"));}}
